int tong(int n){ int s=0; while(n){ s+=n%10; n/=10; } return s; }
int cmp(const void *a, const void *b){
    return tong(*(const int*)a) - tong(*(const int*)b);
}
int a[] = {10002,19,3000,111,81,45,1002,21,10071,203,401};
qsort(a, 11, sizeof(int), cmp);
