typedef struct { int giaTri; int viTriGoc; } PhanTu;
int cmp(const void *a, const void *b){
    const PhanTu *x = a, *y = b;
    int tx = tong(x->giaTri), ty = tong(y->giaTri);
    if(tx != ty) return tx - ty;       // tieu chi chinh
    return x->viTriGoc - y->viTriGoc;  // tieu chi phu
}

void tron(int a[], int tam[], int l, int m, int r){
    int i = l, j = m + 1, k = l;
    while(i <= m && j <= r)
        if(tong(a[i]) <= tong(a[j])) tam[k++] = a[i++]; // <= la mau chot
        else tam[k++] = a[j++];
    while(i <= m) tam[k++] = a[i++];  while(j <= r) tam[k++] = a[j++];
    for(k = l; k <= r; k++) a[k] = tam[k];
}
void mergeSort(int a[], int tam[], int l, int r){
    if(l >= r) return;
    int m = l + (r - l) / 2;
    mergeSort(a, tam, l, m); mergeSort(a, tam, m+1, r);
    tron(a, tam, l, m, r);
}
